<?php
 function PHPMailerAutoload($classname) { $filename = dirname(__FILE__).DIRECTORY_SEPARATOR.'class.'.strtolower($classname).'.php'; if (is_readable($filename)) { require $filename; } } if (version_compare(PHP_VERSION, '5.1.2', '>=')) { spl_autoload_register('PHPMailerAutoload', true, true); } else { function __autoload($classname) { PHPMailerAutoload($classname); } } 